+:root, [data-theme="light"] {
+  --ui-background: #fff;
+  --ui-surface: #f4f4f5;
+  --ui-surface-strong: #e4e4e7;
+  --ui-border: #d4d4d8;
+  --ui-text: #18181b;
+  --ui-text-muted: #52525b;
+  --ui-text-subtle: #71717a;
+  --ui-accent: #4f46e5;
+  --ui-accent-focus: #a5b4fc;
+  --ui-accent-disabled: #c7d2fe;
+  --ui-success-background: #dcfce7;
+  --ui-success-text: #166534;
+  --ui-progress-background: #e0e7ff;
+  --ui-progress-text: #3730a3;
+  --ui-warning-text: #a16207;
+  --ui-error-background: #fef2f2;
+  --ui-error-text: #b91c1c;
+}
+[data-theme="dark"] {
+  --ui-background: #18181a;
+  --ui-surface: #212426;
+  --ui-surface-strong: #2e3434;
+  --ui-border: #49545a;
+  --ui-text: #fff;
+  --ui-text-muted: #c5cdd1;
+  --ui-text-subtle: #8f9da3;
+  --ui-accent: #7efff5;
+  --ui-accent-focus: #7efff5;
+  --ui-accent-disabled: #426158;
+  --ui-success-background: #153d36;
+  --ui-success-text: #8ce8d9;
+  --ui-progress-background: #28345c;
+  --ui-progress-text: #c7d2fe;
+  --ui-warning-text: #fdcd79;
+  --ui-error-background: #500124;
+  --ui-error-text: #ffcada;
+}
+:root { color: var(--ui-text); background: var(--ui-background); font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 13px; }
+* { box-sizing: border-box; }
+body { margin: 0; }
+button, input { font: inherit; }
+button { cursor: pointer; }
+.app-shell { display: flex; flex-direction: column; gap: 18px; min-height: 100vh; padding: 20px; }
+header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
+h1, h2, p { margin: 0; }
+h1 { font-size: 18px; letter-spacing: -0.02em; }
+header p { margin-top: 4px; color: var(--ui-text-subtle); }
+h2 { font-size: 13px; }
+label { display: grid; gap: 6px; color: var(--ui-text); font-weight: 600; }
+label span { font-weight: 400; color: var(--ui-text-subtle); }
+input { width: 100%; border: 1px solid var(--ui-border); border-radius: 6px; padding: 8px 9px; color: var(--ui-text); background: var(--ui-background); }
+input:focus { outline: 2px solid var(--ui-accent-focus); outline-offset: 1px; }
+.source-section { display: grid; gap: 8px; }
+.editor { min-height: 285px; resize: vertical; overflow: auto; border: 1px solid var(--ui-border); border-radius: 7px; padding: 10px; color: var(--ui-text); background: var(--ui-background); font: 12px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre; }
+.editor:focus { outline: 2px solid var(--ui-accent-focus); outline-offset: 1px; }
+.source-note { color: var(--ui-text-subtle); font-size: 12px; line-height: 1.4; }
+.section-heading { display: flex; align-items: center; justify-content: space-between; }
+.viewport-section { display: grid; gap: 8px; }
+.viewport-list { display: grid; gap: 7px; }
+.viewport-row { display: grid; grid-template-columns: minmax(80px, 1fr) 72px 12px 72px 28px; align-items: center; gap: 6px; }
+.viewport-row input { min-width: 0; }
+.icon-button, .text-button, .advanced-toggle { border: 0; background: transparent; color: var(--ui-accent); padding: 4px; }
+.icon-button { color: var(--ui-text-subtle); font-size: 18px; line-height: 1; }
+.icon-button:disabled { opacity: .35; cursor: not-allowed; }
+.advanced-section { border-top: 1px solid var(--ui-surface-strong); padding-top: 12px; }
+.advanced-toggle { padding-left: 0; font-weight: 600; }
+.advanced-panel { display: grid; gap: 12px; padding-top: 10px; }
+.checkbox { display: block; font-weight: 500; }
+.checkbox input { width: auto; margin: 0 7px 0 0; vertical-align: middle; }
+.checkbox span { display: block; margin: 5px 0 0 24px; }
+.advanced-panel output { margin-left: auto; color: var(--ui-text-subtle); font-weight: 400; }
+.analysis { display: grid; gap: 7px; padding: 12px; border-radius: 8px; background: var(--ui-surface); }
+.summary { color: var(--ui-text-muted); }
